/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[error_codes::SESSION_NOT_FOUND];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `auth/revoke-session:sessionNotFound`
    ///
    /// The named `sessionId` is not a session the producer may revoke — it does not exist, was already revoked, or belongs to a subject outside the producer's authority. The consumer MUST answer all three identically, so the code discloses nothing about sessions the producer does not control. A consumer MAY instead answer all three with `revokedCount: 0`; see Conformance.
    ///
    /// Declared `retryable: false`.
    pub const SESSION_NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "auth/revoke-session:sessionNotFound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
